    """A weekday with no opening_hours entry is closed."""
    date = fx.booking_date()
    closed = [h for h in fx.all_week() if h["weekday"] != fx.weekday_of(date)]
    reset(fx.fixture(restaurants=[fx.restaurant(opening_hours=closed)]))
